import{_ as i,c as t,o as n,ae as o}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"UNLEASHING AMERICAN DRONE DOMINANCE","description":"","frontmatter":{"title":"UNLEASHING AMERICAN DRONE DOMINANCE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/06/unleashing-american-drone-dominance/","publishDate":"2025-06-06T17:19:58-04:00"},"headers":[],"relativePath":"executive-orders/2025-06-06-unleashing-american-drone-dominance.md","filePath":"executive-orders/2025-06-06-unleashing-american-drone-dominance.md"}'),r={name:"executive-orders/2025-06-06-unleashing-american-drone-dominance.md"};function a(l,e,s,u,c,p){return n(),t("div",null,e[0]||(e[0]=[o('<h1 id="unleashing-american-drone-dominance" tabindex="-1">UNLEASHING AMERICAN DRONE DOMINANCE <a class="header-anchor" href="#unleashing-american-drone-dominance" aria-label="Permalink to &quot;UNLEASHING AMERICAN DRONE DOMINANCE&quot;">​</a></h1><p>Published: Friday, June 6, 2025</p><ul><li><p><strong>Overview of Drones</strong>:</p><ul><li>Drones (UAS) enhance productivity and create high-skilled jobs.</li><li>They&#39;re transforming multiple industries, including logistics, agriculture, and public safety.</li><li>Emerging technologies like eVTOL aircraft are set to modernize aviation.</li></ul></li><li><p><strong>Integration into National Airspace</strong>:</p><ul><li>The U.S. aims to safely commercialize drone technologies and integrate UAS into the National Airspace System.</li></ul></li><li><p><strong>Key Policies</strong>:</p><ul><li>Accelerate integration through risk-based rulemaking.</li><li>Support domestic commercialization with regulatory clarity.</li><li>Strengthen the drone industrial base and promote exports.</li></ul></li><li><p><strong>Action Items</strong>:</p><ul><li><p><strong>BVLOS Operations</strong>:</p><ul><li>FAA to propose rules for routine BVLOS operations within 30 days.</li><li>Safety metrics for BVLOS operations to be established within 30 days.</li><li>Identify regulatory barriers and propose solutions within 180 days.</li></ul></li><li><p><strong>AI Deployment</strong>:</p><ul><li>Implement AI tools for UAS waiver applications to expedite processes within 120 days.</li></ul></li><li><p><strong>eVTOL Integration Pilot Program</strong>:</p><ul><li>Establish eIPP to accelerate eVTOL deployment, including public request for proposals within 90 days.</li><li>Recommendations and evaluations of the pilot program to be submitted throughout its duration.</li></ul></li></ul></li><li><p><strong>Domestic Manufacturing Prioritization</strong>:</p><ul><li>Agencies to prioritize U.S. manufactured drones.</li><li>Creation of a Covered Foreign Entity List to identify supply chain risks.</li></ul></li><li><p><strong>Export Controls</strong>:</p><ul><li>Review and amend regulations to expedite export of U.S.-manufactured civil UAS to non-adversaries.</li></ul></li><li><p><strong>Department of Defense (DoD) Initiatives</strong>:</p><ul><li>Ensure procurement of U.S. manufactured drones for military use.</li><li>Streamline airspace access for UAS training within 90 days.</li></ul></li><li><p><strong>General Provisions</strong>:</p><ul><li>The order does not alter existing legal authorities.</li><li>Implementation subject to applicable laws and available funds.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/06/unleashing-american-drone-dominance/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/06/unleashing-american-drone-dominance/</a></p>',4)]))}const m=i(r,[["render",a]]);export{g as __pageData,m as default};
